students=[('Adithi H','9000044444','CSE','AKS-CS-001',9.4,180000),('Sahana K','9000055555','ISE','AKS-IS-002',9.1,160000),('Namana','9000066666','ECE','AKS-EC-003',8.8,220000),('Sampreethi','9000077777','AI&ML','AKS-AI-004',9.0,140000),('Akash R','9000088888','Mechanical','AKS-ME-005',8.3,250000),('Gourav H','9000099999','Civil','AKS-CV-006',8.6,130000),('Minnu K','9000100000','ECE','AKS-EC-007',8.9,190000)]
professors=[('Dr Pradeep N','9000011111','admin','Chairperson'),('Usha C','9000022222','reviewer','Scholarship Reviewer'),('Gowri B','9000033333','reviewer','Academic Reviewer')]

def db():
    c=sqlite3.connect(DB); c.row_factory=sqlite3.Row; return c

def rowdicts(cur): return [dict(r) for r in cur.fetchall()]
def phone(x): return ''.join(ch for ch in str(x) if ch.isdigit())[-10:]
def appno(i): return f'AKS-BIET-2026-{i:05d}'

def seed():
    with db() as c:
        c.executescript('''
        create table if not exists users(id integer primary key,name text,phone text unique,role text,dept text);
        create table if not exists profiles(user_id integer unique,roll text,course text,cgpa real,income integer);
        create table if not exists scholarships(id integer primary key,title text,provider text,amount integer,min_cgpa real,max_income integer,seats integer,deadline text,status text,eligibility text);
        create table if not exists applications(id integer primary key,student_id integer,scholarship_id integer,purpose text,status text,score integer,updated text default current_timestamp,unique(student_id,scholarship_id));
        ''')
        if c.execute('select count(*) n from users').fetchone()['n']: return
        for i,p in enumerate(professors,1): c.execute('insert into users values(?,?,?,?,?)',(i,p[0],p[1],p[2],p[3]))
        for i,s in enumerate(students,4):
            c.execute('insert into users values(?,?,?,?,?)',(i,s[0],s[1],'student',s[2]))
            c.execute('insert into profiles values(?,?,?,?,?)',(i,s[3],s[2],s[4],s[5]))
        schemes=[('AKSHARA Merit Excellence Scholarship','BIET Scholarship Cell',75000,8.5,300000,35,'2026-08-31','CGPA 8.5+, verified income certificate and active BIET enrollment'),('Women in Technology Grant','AKSHARA Foundation',95000,8.0,500000,20,'2026-08-20','Female students in computing or electronics with strong academics'),('Need Based Academic Aid','BIET Welfare Board',50000,7.0,200000,60,'2026-07-30','Income below 200000 and CGPA 7.0+'),('Research Innovation Fellowship','BIET Innovation Council',120000,8.8,650000,12,'2026-09-01','Research proposal and CGPA 8.8+')]
        for i,s in enumerate(schemes,1): c.execute('insert into scholarships values(?,?,?,?,?,?,?,?,?,?)',(i,*s,'open'))
        apps=[(4,1,'Tuition fees, academic materials, project work and professional certification expenses.','approved',94),(5,2,'Machine learning research, lab work and technical event participation.','under_review',88),(6,3,'Semester fees, hostel support and academic books.','submitted',82),(7,2,'AI research, lab work and professional training.','approved',91),(8,1,'Design courses, project materials and semester fee payments.','submitted',80),(9,3,'Tuition, transport, books and civil engineering survey equipment.','waitlisted',77),(10,4,'Research participation, technical events and first-year academic expenses.','under_review',86)]
        for a in apps: c.execute('insert into applications(student_id,scholarship_id,purpose,status,score) values(?,?,?,?,?)',a)

HTML='''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AKSHARA BIET Scholarship Management System</title><style>
:root{--n:#082a5f;--b:#0867d8;--o:#f97316;--g:#168250;--r:#c73535;--m:#657286;--l:#dbe3ee;--bg:#eef3f8}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:#101724;font-family:Inter,Segoe UI,Arial,sans-serif}button,input,textarea{font:inherit}button{cursor:pointer}.login{min-height:100vh;display:grid;grid-template-columns:1.2fr .8fr;background:linear-gradient(105deg,rgba(8,42,95,.95),rgba(8,103,216,.76)),var(--bg)}.hero{display:flex;flex-direction:column;justify-content:end;padding:60px 72px;color:white}.hero img{width:190px;height:122px;object-fit:cover;box-shadow:0 22px 55px #0008}.hero h1{font-size:clamp(42px,6vw,78px);line-height:.98;margin:20px 0}.hero p{font-size:19px;max-width:760px;line-height:1.55;color:#e9f1ff}.chips{display:flex;gap:12px;flex-wrap:wrap}.chips span{border:1px solid #ffffff55;background:#ffffff22;padding:13px 16px}.card{background:white;border:1px solid var(--l);box-shadow:0 18px 50px #10172418;padding:22px}.loginbox{align-self:center;justify-self:center;width:min(460px,calc(100% - 28px))}.head{display:flex;gap:14px;align-items:center}.head img{width:76px;height:54px;object-fit:cover}.ey{color:var(--o);font-weight:900;text-transform:uppercase;font-size:12px;margin:0 0 6px}label{display:grid;gap:8px;color:var(--m);font-weight:800;font-size:13px;margin-top:14px}input,textarea{width:100%;border:1px solid var(--l);padding:13px;background:white}.primary{width:100%;border:0;background:linear-gradient(90deg,var(--n),var(--b));color:white;font-weight:900;padding:13px;margin-top:16px}.quick{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:14px}.quick button,.ghost{border:1px solid var(--l);background:white;color:var(--n);font-weight:800;padding:10px}.warn{background:#fff7e8;border:1px solid #f1c36d;color:#7a4b00;padding:12px;margin-top:14px}.hide{display:none!important}.shell{display:grid;grid-template-columns:292px 1fr;min-height:100vh}.side{background:#071b3d;color:white;padding:22px 18px;position:sticky;top:0;height:100vh}.brand{display:flex;gap:12px;align-items:center}.brand img{width:62px;height:48px;object-fit:cover}.brand h2{margin:0;font-size:16px}.brand p{margin:4px 0;color:#a9bad0;font-size:12px}.nav{display:grid;gap:8px;margin-top:22px}.nav button{border:0;text-align:left;background:transparent;color:#dce8f8;padding:12px;font-weight:900}.nav button.active,.nav button:hover{background:#ffffff1c}.deadline{margin-top:22px;background:#f9731629;border:1px solid #f9731655;padding:14px;color:#fff0df}.logout{position:absolute;bottom:18px;left:18px;right:18px;background:transparent;color:white;border:1px solid #ffffff44;padding:11px;font-weight:900}.content{padding:26px}.top{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:18px}.top h1{margin:0;font-size:30px}.pill{display:flex;gap:12px;align-items:center;background:white;border:1px solid var(--l);padding:10px 14px}.avatar{width:42px;height:42px;display:grid;place-items:center;background:#e8f1ff;color:var(--b);font-weight:900}.alert{display:flex;justify-content:space-between;gap:16px;background:white;border-left:5px solid var(--o);padding:14px 16px;margin-bottom:18px}.grid{display:grid;gap:18px}.stats{grid-template-columns:repeat(4,1fr)}.stat .v{font-size:32px;font-weight:950;margin-top:8px}.label{color:var(--m);font-size:12px;font-weight:900;text-transform:uppercase}.two{grid-template-columns:1.3fr .7fr}.row{display:grid;grid-template-columns:1fr auto;gap:12px;border-top:1px solid var(--l);padding:13px 0}.badge{display:inline-flex;align-items:center;min-height:26px;padding:4px 9px;font-size:12px;font-weight:900;background:#edf2f7;color:var(--n);text-transform:capitalize}.unique{background:#fff3e8;color:var(--o);letter-spacing:.3px}.approved,.paid{background:#dcf5e8;color:var(--g)}.rejected{background:#ffe2e2;color:var(--r)}.under_review,.submitted{background:#e4f0ff;color:var(--b)}.waitlisted{background:#fff0d4;color:#94630a}.toolbar{display:flex;justify-content:space-between;gap:12px;margin-bottom:18px}.scheme{grid-template-columns:repeat(3,minmax(260px,1fr))}.scheme .card{border-top:4px solid var(--b)}.amount{font-size:28px;color:var(--b);font-weight:950}.facts{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.fact{background:#f3f7fb;padding:10px;color:var(--m);font-size:12px}.fact strong{display:block;color:#101724;font-size:15px;margin-top:3px}table{width:100%;border-collapse:collapse;background:white}th,td{text-align:left;padding:13px;border-bottom:1px solid var(--l);vertical-align:top}th{background:#f8fafc;color:var(--m);font-size:12px;text-transform:uppercase}.actions{display:flex;gap:8px;flex-wrap:wrap}.actions button{border:0;background:var(--b);color:white;font-weight:900;padding:9px 11px}.faculty{grid-template-columns:repeat(3,1fr)}.faculty .card{border-top:4px solid var(--o)}.toast{position:fixed;right:24px;bottom:24px;background:#101724;color:white;padding:13px 16px}@media(max-width:900px){.login,.shell,.two,.stats,.scheme,.faculty{grid-template-columns:1fr}.side{height:auto;position:static}.logout{position:static;width:100%;margin-top:16px}.hero{padding:36px 22px}.top,.alert,.toolbar{flex-direction:column;align-items:stretch}table{display:block;overflow:auto}}
</style></head><body><main id="app"></main><script>
const LOGO='''+repr(LOGO)+''';let me=null,data={},view='dashboard',phone='';const faculty=[['Dr Pradeep N','Chairperson','9000011111'],['Usha C','Scholarship Reviewer','9000022222'],['Gowri B','Academic Reviewer','9000033333']];const rs=v=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(v||0);async function api(u,o={}){let r=await fetch(u,{headers:{'Content-Type':'application/json'},...o});let j=await r.json().catch(()=>({}));if(!r.ok)throw Error(j.error||'Request failed');return j}function toast(t){let e=document.createElement('div');e.className='toast';e.textContent=t;document.body.append(e);setTimeout(()=>e.remove(),3000)}async function boot(){me=(await api('/api/me')).user;if(!me)return login();await load();shell()}function login(){app.innerHTML=`<section class="login"><div class="hero"><img src="${LOGO}"><p class="ey">BIET Digital Scholarship Cell</p><h1>AKSHARA BIET Scholarship Management System</h1><p>Professional DBMS portal for merit awards, need-based aid, OTP access, review, verification and fund disbursement.</p><div class="chips"><span><b>AKS-2026</b> unique numbers</span><span><b>OTP</b> mobile login</span><span><b>31 Aug</b> final deadline</span></div></div><form class="card loginbox" id="f"><div class="head"><img src="${LOGO}"><div><p class="ey">Secure OTP Access</p><h2>Sign in with mobile</h2></div></div><label>Registered mobile number<input name="phone" value="9000055555"></label><button class="primary">Send OTP</button><label id="or" class="hide">Enter OTP<input name="otp" maxlength="6"></label><button class="primary hide" type="button" id="verify">Verify and Login</button><div class="quick"><button type="button" data-p="9000044444">Adithi</button><button type="button" data-p="9000055555">Sahana</button><button type="button" data-p="9000011111">Principal</button></div><div class="warn"><b>Warning:</b> Do not share OTP, application number, income certificate, bank details or login access.</div><p id="err" style="color:#c73535;font-weight:800"></p></form></section>`;document.querySelectorAll('[data-p]').forEach(b=>b.onclick=()=>f.phone.value=b.dataset.p);f.onsubmit=async e=>{e.preventDefault();try{let p=await api('/api/request-otp',{method:'POST',body:JSON.stringify({phone:f.phone.value})});phone=f.phone.value;or.classList.remove('hide');verify.classList.remove('hide');f.otp.value=p.dev_otp;toast('OTP generated for '+p.name+': '+p.dev_otp)}catch(x){err.textContent=x.message}};verify.onclick=async()=>{try{me=(await api('/api/verify-otp',{method:'POST',body:JSON.stringify({phone,otp:f.otp.value})})).user;await load();shell()}catch(x){err.textContent=x.message}}}
async function load(){data.d=await api('/api/dashboard');data.s=(await api('/api/scholarships')).scholarships;data.a=(await api('/api/applications')).applications;if(me.role!='student')data.st=(await api('/api/students')).students}function shell(){let nav=['dashboard','scholarships','applications'];if(me.role!='student')nav.push('students','professors');app.innerHTML=`<section class="shell"><aside class="side"><div class="brand"><img src="${LOGO}"><div><h2>AKSHARA BIET</h2><p>Scholarship Management System</p></div></div><div class="nav">${nav.map(n=>`<button class="${view==n?'active':''}" onclick="view='${n}';shell()">${n.toUpperCase()}</button>`).join('')}</div><div class="deadline"><b>Final Deadline</b><br>31 Aug 2026, 5:00 PM<br>Late applications move to waitlist.</div><button class="logout" onclick="api('/api/logout',{method:'POST'}).then(()=>location.reload())">Sign out</button></aside><section class="content"><div class="top"><div><h1>${view.toUpperCase()}</h1><p>AKSHARA BIET secure scholarship command portal.</p></div><div class="pill"><div class="avatar">${me.name.split(' ').map(x=>x[0]).slice(0,2).join('')}</div><div><b>${me.name}</b><br>${me.role} - ${me.phone}</div></div></div><div class="alert"><b>Security warning: OTP, bank details, income certificate and application number must remain confidential.</b><span class="badge unique">AKSHARA Secure</span></div><div id="v">${render()}</div></section></section>`}function stat(k,v){return `<div class="card stat"><div class="label">${k}</div><div class="v">${v}</div></div>`}function render(){if(view=='dashboard'){let d=data.d;return `<div class="grid stats">${stat('Open Scholarships',d.open)}${stat('Applications',d.apps)}${stat('Approved Awards',d.approved)}${stat('Funds Disbursed',rs(d.paid))}</div><div class="grid two" style="margin-top:18px"><div class="card"><h2>Application Pipeline</h2>${d.pipe.map(x=>`<div class="row"><b>${x.status.replace('_',' ')}</b><span class="badge ${x.status}">${x.total}</span></div>`).join('')}</div><div class="card"><h2>Deadlines</h2>${data.s.map(x=>`<div class="row"><b>${x.title}</b><span class="badge unique">${x.deadline}</span></div>`).join('')}</div></div>`}if(view=='scholarships')return `<div class="grid scheme">${data.s.map((s,i)=>`<div class="card"><span class="badge unique">SCHEME-${String(i+1).padStart(3,'0')}</span><h2>${s.title}</h2><div class="amount">${rs(s.amount)}</div><p>${s.eligibility}</p><div class="facts"><div class="fact">Min CGPA<strong>${s.min_cgpa}</strong></div><div class="fact">Income<strong>${rs(s.max_income)}</strong></div><div class="fact">Seats<strong>${s.seats}</strong></div><div class="fact">Deadline<strong>${s.deadline}</strong></div></div></div>`).join('')}</div>`;if(view=='applications')return `<table><tr><th>Unique No</th><th>Student</th><th>Scholarship</th><th>Status</th><th>Score</th></tr>${data.a.map(a=>`<tr><td><span class="badge unique">${a.no}</span></td><td>${a.student}<br><small>${a.roll||''}</small></td><td>${a.scholarship}</td><td><span class="badge ${a.status}">${a.status.replace('_',' ')}</span></td><td>${a.score}/100</td></tr>`).join('')}</table>`;if(view=='students')return `<table><tr><th>Name</th><th>Roll</th><th>Course</th><th>CGPA</th><th>Income</th></tr>${data.st.map(s=>`<tr><td>${s.name}</td><td>${s.roll}</td><td>${s.course}</td><td>${s.cgpa}</td><td>${rs(s.income)}</td></tr>`).join('')}</table>`;return `<div class="grid faculty">${faculty.map(f=>`<div class="card"><p class="ey">Scholarship Authority</p><h2>${f[0]}</h2><p>${f[1]}</p><span class="badge unique">${f[2]}</span></div>`).join('')}</div>`}
boot();</script></body></html>'''

def current(h):
    jar=cookies.SimpleCookie(h.headers.get('Cookie','')); t=jar.get('akshara'); uid=SESSIONS.get(t.value) if t else None
    if not uid: return None
    with db() as c: r=c.execute('select * from users where id=?',(uid,)).fetchone(); return dict(r) if r else None
class H(BaseHTTPRequestHandler):
    def log_message(self,*a): pass
    def js(self,x,code=200,cookie=None):
        b=json.dumps(x).encode(); self.send_response(code); self.send_header('Content-Type','application/json'); self.send_header('Content-Length',str(len(b))); 
        if cookie:self.send_header('Set-Cookie',cookie)
        self.end_headers(); self.wfile.write(b)
    def body(self): return json.loads(self.rfile.read(int(self.headers.get('Content-Length',0) or 0)) or b'{}')
    def do_GET(self):
        if self.path=='/':
            b=HTML.encode(); self.send_response(200); self.send_header('Content-Type','text/html'); self.send_header('Content-Length',str(len(b))); self.end_headers(); self.wfile.write(b); return
        u=current(self)
        with db() as c:
            if self.path=='/api/me': return self.js({'user':u})
            if not u: return self.js({'error':'Authentication required'},401)
            if self.path=='/api/dashboard':
                pipe=rowdicts(c.execute('select status,count(*) total from applications group by status'))
                return self.js({'open':c.execute("select count(*) n from scholarships where status='open'").fetchone()['n'],'apps':c.execute('select count(*) n from applications').fetchone()['n'],'approved':c.execute("select count(*) n from applications where status='approved'").fetchone()['n'],'paid':75000,'pipe':pipe})
            if self.path=='/api/scholarships': return self.js({'scholarships':rowdicts(c.execute('select * from scholarships order by deadline'))})
            if self.path=='/api/applications':
                q='''select a.*,u.name student,p.roll,s.title scholarship from applications a join users u on u.id=a.student_id left join profiles p on p.user_id=u.id join scholarships s on s.id=a.scholarship_id'''; args=()
                if u['role']=='student': q+=' where a.student_id=?'; args=(u['id'],)
                out=[]
                for r in rowdicts(c.execute(q,args)): r['no']=appno(r['id']); out.append(r)
                return self.js({'applications':out})
            if self.path=='/api/students': return self.js({'students':rowdicts(c.execute('select u.name,p.* from users u join profiles p on p.user_id=u.id order by p.cgpa desc'))})
        self.js({'error':'not found'},404)
    def do_POST(self):
        p=self.body()
        if self.path=='/api/request-otp':
            ph=phone(p.get('phone'))
            with db() as c: u=c.execute('select * from users where substr(replace(phone," ",""),-10)=?',(ph,)).fetchone()
            if not u: return self.js({'error':'Mobile number not registered'},404)
            code=str(secrets.randbelow(900000)+100000); OTPS[ph]=(code,u['id'],time.time()+300); print('OTP',ph,code,flush=True); return self.js({'ok':1,'dev_otp':code,'name':u['name']})
        if self.path=='/api/verify-otp':
            ph=phone(p.get('phone')); rec=OTPS.get(ph)
            if not rec or rec[2]<time.time(): return self.js({'error':'OTP expired'},400)
            if str(p.get('otp'))!=rec[0]: return self.js({'error':'Invalid OTP'},400)
            with db() as c: u=dict(c.execute('select * from users where id=?',(rec[1],)).fetchone())
            tok=secrets.token_urlsafe(24); SESSIONS[tok]=u['id']; return self.js({'user':u},cookie=f'akshara={tok}; HttpOnly; SameSite=Lax; Path=/')
        if self.path=='/api/logout': return self.js({'ok':1},cookie='akshara=; Max-Age=0; Path=/')
        self.js({'error':'not found'},404)

if __name__=='__main__':
    seed(); port=int(os.environ.get('PORT','8000')); print(APP,'running on',port,flush=True); ThreadingHTTPServer(('0.0.0.0',port),H).serve_forever()
